import React,{useEffect,useState} from 'react';
import {ShieldCheck,KeyRound,Download,ArrowRight} from 'lucide-react';
import {api,Button,Field,Notice,Tag,errorText,download} from './ui';

function QrCode({uri}) {
  const [svg,setSvg]=useState('');
  useEffect(()=>{let live=true;import('qrcode').then(({default:QR})=>QR.toString(uri,{type:'svg',margin:1,width:176})).then(markup=>{if(live)setSvg(markup);}).catch(()=>{});return()=>{live=false;};},[uri]);
  // The markup is generated by the QR library from our own otpauth address, never from user HTML.
  return svg?<div className="qr-code" role="img" aria-label="QR code" dangerouslySetInnerHTML={{__html:svg}}/>:null;
}

export default function AccountSecurity({L,me}) {
  const [state,setState]=useState(null),[busy,setBusy]=useState(false),[error,setError]=useState(null),[notice,setNotice]=useState('');
  const [setup,setSetup]=useState(null),[codes,setCodes]=useState(null);
  const refresh=()=>api('/auth/security').then(setState).catch(setError);
  useEffect(()=>{refresh();},[]);
  const run=async fn=>{setBusy(true);setError(null);setNotice('');try{await fn();}catch(e){setError(e);}finally{setBusy(false);}};
  if(!state)return <p className="muted">{error?errorText(error,L):L('Wird geladen …','Nalaganje …')}</p>;
  const passwordField=state.hasPassword&&<Field label={L('Aktuelles Passwort','Trenutno geslo')} name="password" type="password" autoComplete="current-password" required maxLength={128}/>;
  const form=handler=>e=>{e.preventDefault();const form=e.currentTarget,body=Object.fromEntries(new FormData(form));run(async()=>{await handler(body);form.reset?.();});};
  return <div className="security-grid">
    {error&&<Notice tone="error">{errorText(error,L)}</Notice>}{notice&&<Notice>{notice}</Notice>}
    <section className="panel"><div className="panel-title"><div><span className="eyebrow">TWO-FACTOR SIGN-IN</span><h3>{L('Zwei-Faktor-Anmeldung','Dvostopenjska prijava')}</h3></div><Tag tone={state.mfaEnabled?'mint':''}>{state.mfaEnabled?L('AKTIV','VKLOPLJENO'):L('AUS','IZKLOPLJENO')}</Tag></div>
      <p>{L('Schützt Ihr Konto zusätzlich zum Passwort mit einem Code aus einer Authenticator-App (z. B. 1Password, Google oder Microsoft Authenticator). Empfohlen für alle, die Gehaltsdaten verwalten.','Račun poleg gesla zaščiti s kodo iz aplikacije za preverjanje (npr. 1Password, Google ali Microsoft Authenticator). Priporočeno za vse, ki upravljajo podatke o plačah.')}</p>
      {codes?<><Notice>{L('Bewahren Sie diese Wiederherstellungscodes sicher auf. Jeder Code funktioniert nur einmal und wird nicht erneut angezeigt. Andere Geräte wurden abgemeldet.','Te kode za obnovitev shranite na varno mesto. Vsaka velja samo enkrat in se ne prikaže znova. Druge naprave so bile odjavljene.')}</Notice><div className="backup-codes">{codes.map(c=><code key={c}>{c}</code>)}</div><div className="button-row"><Button secondary onClick={()=>download(codes.join('\n'),'equitensa-recovery-codes.txt','text/plain;charset=utf-8')}><Download size={15}/>{L('Als Datei speichern','Shrani kot datoteko')}</Button><Button onClick={()=>{setCodes(null);refresh();}}>{L('Codes gespeichert','Kode so shranjene')}<ArrowRight size={16}/></Button></div></>
      :state.mfaEnabled?<><p>{L('Verbleibende Wiederherstellungscodes','Preostale kode za obnovitev')}: <strong>{state.backupCodesLeft}</strong></p>
        <form onSubmit={form(async body=>{await api('/auth/mfa/disable',body);setNotice(L('Zwei-Faktor-Anmeldung deaktiviert.','Dvostopenjska prijava je izklopljena.'));await refresh();})}>{passwordField}<Field label={L('Code aus der App oder Wiederherstellungscode','Koda iz aplikacije ali koda za obnovitev')} name="code" autoComplete="one-time-code" required maxLength={20}/><Button secondary type="submit" busy={busy}>{L('Deaktivieren','Izklopi')}</Button></form></>
      :setup?<><p>{L('Scannen Sie den QR-Code mit Ihrer Authenticator-App oder geben Sie den Schlüssel manuell ein. Danach den sechsstelligen Code bestätigen.','Skenirajte kodo QR z aplikacijo za preverjanje ali ročno vnesite ključ. Nato potrdite šestmestno kodo.')}</p><QrCode uri={setup.otpauth}/><code className="mfa-secret">{setup.secret}</code>
        <form onSubmit={form(async body=>{const r=await api('/auth/mfa/enable',body);setCodes(r.backupCodes);setSetup(null);})}><Field label={L('Sechsstelliger Code','Šestmestna koda')} name="code" inputMode="numeric" autoComplete="one-time-code" pattern="[0-9]{6}" maxLength={6} required/><Button type="submit" busy={busy}>{L('Bestätigen und aktivieren','Potrdi in vklopi')}<ArrowRight size={16}/></Button></form></>
      :<form onSubmit={form(async body=>setSetup(await api('/auth/mfa/setup',body)))}>{passwordField}<Button type="submit" busy={busy}><ShieldCheck size={16}/>{L('Einrichten','Nastavi')}</Button></form>}
    </section>
    {state.hasPassword&&<section className="panel"><div className="panel-title"><div><span className="eyebrow">PASSWORD</span><h3>{L('Passwort ändern','Sprememba gesla')}</h3></div><KeyRound size={22}/></div>
      <p>{L('Nach der Änderung werden alle anderen Geräte abgemeldet.','Po spremembi bodo vse druge naprave odjavljene.')}</p>
      <form onSubmit={form(async body=>{await api('/auth/password',body);setNotice(L('Passwort geändert. Andere Geräte wurden abgemeldet.','Geslo je spremenjeno. Druge naprave so bile odjavljene.'));})}><Field label={L('Aktuelles Passwort','Trenutno geslo')} name="password" type="password" autoComplete="current-password" required maxLength={128}/><Field label={L('Neues Passwort','Novo geslo')} name="newPassword" type="password" autoComplete="new-password" minLength={12} maxLength={128} required hint={L('Mindestens 12 Zeichen','Vsaj 12 znakov')}/><Button type="submit" busy={busy}>{L('Passwort ändern','Spremeni geslo')}</Button></form></section>}
    <section className="panel"><span className="eyebrow">ACCOUNT</span><h3>{me.user.email}</h3><p>{state.emailVerified?L('E-Mail-Adresse bestätigt.','E-poštni naslov je potrjen.'):L('E-Mail-Adresse noch nicht bestätigt.','E-poštni naslov še ni potrjen.')}</p></section>
  </div>;
}
